create table private.push_receipts(ticket_id text primary key,token text not null,created_at timestamptz not null default now(),checked_at timestamptz,error text);
create function public.record_push_ticket(ticket text,device_token text) returns void language sql security definer set search_path='' as $$ insert into private.push_receipts(ticket_id,token) values(ticket,device_token) on conflict do nothing $$;
create function public.pending_push_receipts() returns table(ticket_id text,token text) language sql security definer set search_path='' as $$ select ticket_id,token from private.push_receipts where checked_at is null and created_at<now()-interval '15 minutes' order by created_at limit 100 $$;
create function public.finish_push_receipt(ticket text,error_text text default null) returns void language plpgsql security definer set search_path='' as $$ declare device text; begin update private.push_receipts set checked_at=now(),error=left(error_text,300) where ticket_id=ticket returning token into device; if error_text='DeviceNotRegistered' then delete from public.push_tokens where token=device; end if; end $$;
revoke all on function public.record_push_ticket(text,text),public.pending_push_receipts(),public.finish_push_receipt(text,text) from public,anon,authenticated;
grant execute on function public.record_push_ticket(text,text),public.pending_push_receipts(),public.finish_push_receipt(text,text) to service_role;
